CREATE TABLE IF NOT EXISTS permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, module TEXT NOT NULL, resource TEXT NOT NULL, action TEXT NOT NULL, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), code TEXT NOT NULL, name TEXT NOT NULL, is_system BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_by UUID, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS role_permissions (role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id UUID NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, granted_at TIMESTAMPTZ NOT NULL DEFAULT now(), granted_by UUID, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS user_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id), user_id UUID NOT NULL REFERENCES app_users(id), role_id UUID NOT NULL REFERENCES roles(id), scope_type TEXT NOT NULL CHECK(scope_type IN ('GLOBAL','CAMPUS','DEPARTMENT','SELF')), scope_id UUID, valid_from TIMESTAMPTZ NOT NULL DEFAULT now(), valid_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_by UUID, UNIQUE(user_id,role_id,scope_type,scope_id,valid_from));
CREATE OR REPLACE VIEW v_user_permissions AS SELECT ur.user_id, ur.tenant_id, p.code AS permission_code, ur.scope_type, ur.scope_id FROM user_roles ur JOIN roles r ON r.id=ur.role_id AND r.is_active JOIN role_permissions rp ON rp.role_id=r.id JOIN permissions p ON p.id=rp.permission_id WHERE ur.valid_from <= now() AND (ur.valid_to IS NULL OR ur.valid_to > now());
